class Solution:
    def mostPopularCreator(self, creators: List[str], ids: List[str], views: List[int]) -> List[List[str]]:
        best = {}
        mx = 0
        for c, i, v in zip(creators, ids, views):
            if c not in best:
                best[c] = [v, v, i]
            else:
                b = best[c]
                b[0] += v
                if v > b[1] or (v == b[1] and i < b[2]):
                    b[1], b[2] = v, i
            mx = max(mx, best[c][0])
        return [[c, b[2]] for c, b in best.items() if b[0] == mx]

