class Solution {
public:
    vector<vector<string>> mostPopularCreator(vector<string>& creators, vector<string>& ids, vector<int>& views) {
        unordered_map<string, array<long long,3>> best;
        long long mx = 0;
        for (int k = 0; k < (int)creators.size(); k++) {
            auto it = best.find(creators[k]);
            if (it == best.end()) {
                best[creators[k]] = {views[k], (long long)views[k], -1LL};
                best[creators[k]][2] = 0;
                auto &b = best[creators[k]];
                b = {views[k], views[k], 0};
                best[creators[k]] = {(long long)views[k], (long long)views[k], 0};
                mx = max(mx, (long long)views[k]);
            } else {
                auto &b = it->second;
                b[0] += views[k];
                if (views[k] > b[1] || (views[k] == b[1] && ids[k] < ids[b[2]])) b[1] = views[k], b[2] = k;
                mx = max(mx, b[0]);
            }
        }
        vector<vector<string>> res;
        for (auto& [c, b] : best)
            if (b[0] == mx) res.push_back({c, ids[b[2]]});
        return res;
    }
};

