class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, long[]> best = new HashMap<>();
        long mx = 0;
        Map<String, String> bestId = new HashMap<>();
        for (int k = 0; k < creators.length; k++) {
            long[] b = best.get(creators[k]);
            if (b == null) {
                best.put(creators[k], new long[]{views[k]});
                bestId.put(creators[k], ids[k]);
                b = best.get(creators[k]);
            } else {
                String cur = bestId.get(creators[k]);
                if (views[k] > b[0] || (views[k] == b[0] && ids[k].compareTo(cur) < 0))
                    bestId.put(creators[k], ids[k]);
                b[0] += views[k];
            }
            mx = Math.max(mx, b[0]);
        }
        List<List<String>> res = new ArrayList<>();
        for (var e : best.entrySet())
            if (e.getValue()[0] == mx)
                res.add(Arrays.asList(e.getKey(), bestId.get(e.getKey())));
        return res;
    }
}

