var mostPopularCreator = function(creators, ids, views) {
    const best = new Map();
    let mx = 0;
    for (let k = 0; k < creators.length; k++) {
        const c = creators[k];
        if (!best.has(c)) best.set(c, { total: 0, bv: -1, bid: "" });
        const b = best.get(c);
        b.total += views[k];
        if (views[k] > b.bv || (views[k] === b.bv && ids[k] < b.bid)) { b.bv = views[k]; b.bid = ids[k]; }
        mx = Math.max(mx, b.total);
    }
    const res = [];
    for (const [c, b] of best) if (b.total === mx) res.push([c, b.bid]);
    return res;
};

