class Solution:
    def mostPopularCreator(self, creators: List[str], ids: List[str], views: List[int]) -> List[List[str]]:
        idx = sorted(range(len(creators)), key=lambda k: (creators[k], -views[k], ids[k]))
        total = {}
        first = {}
        for k in idx:
            c = creators[k]
            total[c] = total.get(c, 0) + views[k]
            if c not in first: first[c] = ids[k]
        mx = max(total.values())
        return [[c, first[c]] for c in total if total[c] == mx]

