class Solution {
public:
    vector<vector<string>> mostPopularCreator(vector<string>& creators, vector<string>& ids, vector<int>& views) {
        int n = creators.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int x, int y) {
            if (creators[x] != creators[y]) return creators[x] < creators[y];
            if (views[x] != views[y]) return views[x] > views[y];
            return ids[x] < ids[y];
        });
        unordered_map<string, long long> total;
        unordered_map<string, string> first;
        for (int k : idx) {
            total[creators[k]] += views[k];
            if (!first.count(creators[k])) first[creators[k]] = ids[k];
        }
        long long mx = 0;
        for (auto& [c, t] : total) mx = max(mx, t);
        vector<vector<string>> res;
        for (auto& [c, t] : total) if (t == mx) res.push_back({c, first[c]});
        return res;
    }
};

