class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Integer[] idx = new Integer[creators.length];
        for (int i = 0; i < idx.length; i++) idx[i] = i;
        Arrays.sort(idx, (x, y) -> {
            int c = creators[x].compareTo(creators[y]);
            if (c != 0) return c;
            if (views[x] != views[y]) return views[y] - views[x];
            return ids[x].compareTo(ids[y]);
        });
        Map<String, Long> total = new HashMap<>();
        Map<String, String> first = new HashMap<>();
        for (int k : idx) {
            total.merge(creators[k], (long) views[k], Long::sum);
            first.putIfAbsent(creators[k], ids[k]);
        }
        long mx = Collections.max(total.values());
        List<List<String>> res = new ArrayList<>();
        for (var e : total.entrySet())
            if (e.getValue() == mx) res.add(Arrays.asList(e.getKey(), first.get(e.getKey())));
        return res;
    }
}

