var mostPopularCreator = function(creators, ids, views) {
    const idx = [...creators.keys()].sort((x, y) =>
        creators[x] !== creators[y] ? creators[x] < creators[y] ? -1 : 1 :
        views[x] !== views[y] ? views[y] - views[x] :
        ids[x] < ids[y] ? -1 : 1);
    const total = {}, first = {};
    for (const k of idx) {
        total[creators[k]] = (total[creators[k]] || 0) + views[k];
        if (!(creators[k] in first)) first[creators[k]] = ids[k];
    }
    const mx = Math.max(...Object.values(total));
    return Object.keys(total).filter(c => total[c] === mx).map(c => [c, first[c]]);
};
